        MainReelMediator.prototype.getSymbolsForReel = function (id, reelset) {
            var response = this._server.getLogicResponse();
            if (!response || !response.reelSpinData || !response.reelSpinData[reelset]) {
                return [];
            }
            var bandsetIndex = response.reelSpinData[reelset].reelsetIndex;
            var bandsets = this._server.getInitResponse().reelsData.reels[bandsetIndex].getAllStrips();
            var symbols = this.replaceSpecialSymbols(id, response.reelSpinData[reelset].reelsetIndex, response.clumpData.smallSymbolId);
            var symbolsOut = [];
            for (var y = 0; y < 4; y++) {
                var index = response.reelSpinData[reelset].reelStops[id] + y - 1;
                if (index < 0) {
                    index = bandsets[id].getSymbols().length - (index * -1);
                }
                if (index >= bandsets[id].getSymbols().length) {
                    index = index - bandsets[id].getSymbols().length;
                }
                symbolsOut.push(symbols[index]);
            }
            return symbolsOut;
        };
