        UIViewMediator.prototype.getTotalBets = function (bets) {
            var totalBetS = [];
            for (var i = 0; i < bets.length; i++) {
                totalBetS.push(bets[i].getBetMultiplier());
            }
            var betvalues = this.view.getBetValues(totalBetS);
            var finalBetValues = this.view.removeCurrency(this.view.getCurrencySym(), betvalues);
            return finalBetValues;
        };
        UIViewMediator.prototype.onIdle = function (e) {
            if (!this._history.getIsHistoryReplay()) {
                this.view.setGameState(sgigame.GamePlayState.GameIdle);
            }
            this.checkLineButtons();
            this.checkBetButtons();
            if (this._server.getLogicResponse() != undefined) {
                var totalWin = this._server.getLogicResponse().baseGameData.totalWagerWin;
                if (totalWin <= 0) {
                    this.onStakeChanged();
                }
            }
            if (this._skipModel.skipped) {
                this.view.updateLineWinMeter("");
            }
            this.onStakeChanged();
            //this.view.getSpinButton().enabled = true;
        };
