            this.view.setDefaultLineIndex(this._paylinecountController.getCurrentLine());
            sgigame.Bet.lineCount = this._paylinecountController.getCurrentLine();
            this.onStakeChanged();
            this.view.getProview().setLineCount(e.lineCount);
