        UIViewMediator.prototype.onFSTriggered = function (e) {
            this.view.updateLineWinMeter(this._translator.findByKey("Feature_triggered"));
        };
        // Update top bar
        UIViewMediator.prototype.updateTopBarBalance = function (value, type) {
            if (this._partnerAdapterEventModel.balanceDisplayEventListener && value > 0) {
                var cashBalance = 0;
                var freebetBalance = 0;
                var balance = value;
                // always update the top bar balance real/fun/openbet/regular
                cashBalance = value;
                if (this._server.getLogicResponse() && !this._isRestore) {
                    if (this._server.getLogicResponse().payloadData && this._server.getLogicResponse().payloadData[type]) {
                        var payloadData = this._server.getLogicResponse().payloadData[type];
                        cashBalance = payloadData.CASH;
                        freebetBalance = payloadData.FREEBET;
                    }
                    else if (this._server.getInitResponse()) {
                        if (this._server.getInitResponse().payloadData && this._server.getInitResponse().payloadData[sgigame.PayloadData.TYPE_INIT]) {
                            var payloadData = this._server.getInitResponse().payloadData[sgigame.PayloadData.TYPE_INIT];
                            freebetBalance = payloadData.FREEBET;
                            cashBalance = balance - freebetBalance;
                        }
                    }
                }
                else if (this._server.getInitResponse()) {
                    if (this._server.getInitResponse().payloadData && this._server.getInitResponse().payloadData[sgigame.PayloadData.TYPE_INIT]) {
                        var payloadData = this._server.getInitResponse().payloadData[sgigame.PayloadData.TYPE_INIT];
                        freebetBalance = payloadData.FREEBET;
                        cashBalance = balance - freebetBalance;
                    }
                }
                var event = new util.BalanceDisplayEvent(cashBalance, freebetBalance, balance);
                this._partnerAdapterEventModel.balanceDisplayEventListener.handlePlatformDisplayEvent(event);
            }
        };
        UIViewMediator.prototype.updatePartner = function (amount) {
            if (this._partnerAdapterEventModel.winDisplayEventListener) {
                var event = new util.WinDisplayEvent(amount);
                this._partnerAdapterEventModel.winDisplayEventListener.handleWinDisplayEvent(event);
            }
        };
        UIViewMediator.prototype.checkBigWinLevel = function (bet, win) {
            var level = 0;
            var winMultiple = win / bet;
            level = sgigame.GameConfig.bigWinThresholds.length - 1;
            var winMultipleFromTable = sgigame.GameConfig.bigWinThresholds[level];
            while (winMultiple <= winMultipleFromTable) {
                level--;
                winMultipleFromTable = sgigame.GameConfig.bigWinThresholds[level];
            }
            return level;
        };
        UIViewMediator.prototype.calculateBangLevel = function (bet, win) {
            var level = 0;
            var winMultiple = win / bet;
            level = sgigame.GameConfig.bangThresholds.length - 1;
            var winMultipleFromTable = sgigame.GameConfig.bangThresholds[level];
            while (winMultiple <= winMultipleFromTable) {
                level--;
                winMultipleFromTable = sgigame.GameConfig.bangThresholds[level];
            }
            return level;
        };
